themes.ui_json:
{
  "version": 2,
  "theme": {
    "appearance": {
      "color_scheme": "auto",
      "preset": "minimal"
    },
    "features": {
      "color_scheme_switch": {
        "enabled": true
      },
      "image_optimization": {
        "enabled": true
      },
      "link_prefetch": {
        "enabled": false
      }
    },
    "leftbar": {
      "brand": {
        "image": {
          "src": "/uploads/avatar.png"
        },
        "name": "Stellar 2.0 验收站",
        "tagline": "独立虚构数据"
      },
      "menu": [
        {
          "icon": "default:documents",
          "id": "post",
          "title": "post",
          "url": "/"
        },
        {
          "icon": "default:documents",
          "id": "wiki",
          "title": "wiki",
          "url": "/wiki/"
        },
        {
          "icon": "default:documents",
          "id": "topic",
          "title": "topic",
          "url": "/topic/"
        },
        {
          "icon": "default:documents",
          "id": "notebook",
          "title": "notebook",
          "url": "/notebooks/"
        },
        {
          "icon": "default:documents",
          "id": "settings",
          "title": "settings",
          "url": "/settings/"
        },
        {
          "icon": "default:documents",
          "id": "tags",
          "title": "tags",
          "url": "/tags-showcase/"
        },
        {
          "icon": "default:documents",
          "id": "moments",
          "title": "moments",
          "url": "/moments/"
        },
        {
          "icon": "default:documents",
          "id": "about",
          "title": "about",
          "url": "/about/"
        }
      ]
    },
    "profiles": {
      "error": {
        "image": "/uploads/cover.png"
      },
      "post": {
        "rightbar": {
          "widgets": [
            "author",
            "toc"
          ]
        }
      }
    },
    "article": {
      "listing": {
        "pinned_layout": "carousel",
        "card_layout": "hero",
        "cover_ratio": 2.4,
        "excerpt_length": 160,
        "show_tags": true
      },
      "show_reading_time": true,
      "footer": {
        "share": [
          "qrcode",
          "weibo",
          "x",
          "telegram",
          "whatsapp",
          "email"
        ],
        "license": "Theme T3 {author.name} {author.url}",
        "show_tags": true
      }
    },
    "preconnect": [
      "http://127.0.0.1:8111/path",
      "http://127.0.0.1:8111"
    ],
    "canonical": {
      "host": "127.0.0.1",
      "allowed_hosts": [
        "localhost",
        "127.0.0.1",
        "t3-mirror.test"
      ]
    },
    "inject": {
      "head_begin": "<meta name=\"t3-theme-head_begin\" content=\"present\">",
      "head_end": "<meta name=\"t3-theme-head_end\" content=\"present\">",
      "body_begin": "<div data-t3-theme=\"body_begin\"></div>",
      "body_end": "<div data-t3-theme=\"body_end\"></div>"
    },
    "services": {
      "github": {
        "api_url": "http://127.0.0.1:8113/t3-github"
      },
      "contributors": {
        "provider": "github",
        "github": {
          "repositories": [
            {
              "source_prefix": "_posts/",
              "repository": "fixture/broad",
              "branch": "broad"
            },
            {
              "source_prefix": "_posts/t3-",
              "repository": "fixture/narrow",
              "branch": "narrow"
            }
          ]
        }
      }
    }
  },
  "blog_extensions": {
    "ai": {
      "ask": {
        "allow_user_llm": false,
        "enabled": false
      },
      "summary": {
        "allow_user_api": false,
        "enabled": false
      }
    },
    "data": {
      "authors": {
        "admin": {
          "avatar": "/uploads/avatar.png",
          "description": "虚构作者",
          "hidden": false,
          "name": "验收管理员"
        },
        "writer": {
          "avatar": "/uploads/avatar.png",
          "hidden": false,
          "name": "第二作者"
        }
      },
      "defaultAuthor": {
        "avatar": "/uploads/avatar.png",
        "description": "默认作者组件样本",
        "name": "验收管理员",
        "path": "/author/admin/"
      },
      "wiki": [
        "galaxy",
        "strands",
        "light-rays",
        "ferrofluid",
        "video"
      ]
    },
    "friends": {
      "check_interval": 0,
      "snapshot_interval": 0
    },
    "native_comments": {
      "enabled": true,
      "gravatar_mirror": "http://127.0.0.1:8113/fixture-unavailable/avatar",
      "moderation": false,
      "notify": {
        "enabled": false
      },
      "title": "原生评论验收"
    },
    "search": {
      "provider": "go"
    },
    "site": {
      "language": "zh-CN",
      "per_page": 2
    }
  }
}

